function resolveOwn(sections, lang) {
	return sections.map((s) => ({
		id: s.id,
		title: s.title[lang],
		blocks: s.blocks.map((b) => ({
			...b.heading ? { heading: b.heading[lang] } : {},
			...b.paragraphs ? { paragraphs: b.paragraphs.map((p) => p[lang]) } : {},
			...b.list ? {
				list: b.list.map((p) => p[lang]),
				ordered: b.ordered
			} : {},
			...b.code ? { code: b.code } : {}
		}))
	}));
}
